CoreStdlibSupportedDTO dto = new CoreStdlibSupportedDTO();
dto.Name = 'Cabin';
dto.Count = 3;
dto.Amount = 12.34;
dto.Tags = new List<String>{'spruce', 'lake'};
String compact = JSON.serialize(dto);
System.assert(compact.contains('"Name":"Cabin"'));
System.assert(compact.contains('"Count":3'));
System.assert(compact.contains('"Amount":12.34'));
System.assert(compact.contains('"Tags":["spruce","lake"]'));
String pretty = JSON.serializePretty(dto);
System.assert(pretty.contains('"Name" : "Cabin"'));
System.assert(pretty.contains('"Count" : 3'));
System.assert(pretty.contains('"Amount" : 12.34'));
System.assert(pretty.contains('"Tags" : [ "spruce", "lake" ]'));
CoreStdlibSupportedDTO decoded = (CoreStdlibSupportedDTO) JSON.deserialize(compact, CoreStdlibSupportedDTO.class);
System.assertEquals('Cabin', decoded.Name);
System.assertEquals(3, decoded.Count);
System.assertEquals(12.34, decoded.Amount);
System.assertEquals('lake', decoded.Tags[1]);
